<template><section class="office-section organization-panel" v-loading="loading"><div class="office-toolbar"><h3>组织与权限</h3><el-button v-if="admin" @click="department()">新建部门</el-button></div><el-tabs v-model="tab"><el-tab-pane label="部门" name="departments"><el-tree :data="tree" node-key="id" :props="{label:'name',children:'children'}" default-expand-all><template #default="{data}"><div class="dept-row"><span>{{ data.name }}</span><div v-if="admin" class="office-actions"><el-button circle title="编辑部门" @click.stop="department(data)"><span class="material-symbols-outlined">edit</span></el-button><el-button circle title="删除部门" @click.stop="deleteDepartment(data)"><span class="material-symbols-outlined">delete</span></el-button></div></div></template></el-tree><el-empty v-if="!departments.length" description="暂无部门" :image-size="60"/></el-tab-pane>
<el-tab-pane label="角色" name="roles"><div class="office-toolbar"><h3>自定义角色</h3><el-button v-if="admin" @click="role()">新建角色</el-button></div><el-table :data="roles"><el-table-column prop="name" label="名称"/><el-table-column label="操作权限" min-width="210"><template #default="{row}">{{ allowed(row.permissions) }}</template></el-table-column><el-table-column v-if="admin" label="操作" width="100"><template #default="{row}"><el-button circle title="编辑角色" @click="role(row)"><span class="material-symbols-outlined">edit</span></el-button><el-button circle title="删除角色" @click="deleteRole(row)"><span class="material-symbols-outlined">delete</span></el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane v-if="admin" label="成员权限" name="members"><div class="office-toolbar"><el-button @click="importInput?.click()">Excel 导入成员</el-button><input ref="importInput" type="file" accept=".xls,.xlsx" hidden @change="importMembers"/></div><el-table :data="members"><el-table-column prop="name" label="成员" min-width="120"/><el-table-column label="部门 / 自定义角色" min-width="220"><template #default="{row}">{{ departments.find(d=>String(d.id)===String(row.deptId))?.name||'未分配' }} / {{ roles.find(r=>String(r.id)===String(row.customRoleId))?.name||'预设角色' }}</template></el-table-column><el-table-column prop="lastActive" label="最后登录" min-width="170"/><el-table-column label="权限" width="80"><template #default="{row}"><el-button v-if="String(row.userId)!==ownerId" circle title="成员权限" @click="member(row)"><span class="material-symbols-outlined">manage_accounts</span></el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane v-if="admin" label="空间设置" name="settings"><form class="office-form space-form" @submit.prevent="saveSpace"><label>名称<el-input v-model="space.name" maxlength="100"/></label><label>Logo 图片地址<el-input v-model="space.logo" maxlength="255"/></label><label>简介<el-input v-model="space.description" type="textarea" maxlength="500"/></label><label>存储配额（GB）<el-input-number v-model="quotaGB" :min="0.001" :max="1024" :precision="3"/></label><el-button type="primary" native-type="submit">保存空间</el-button></form><div v-if="userId===ownerId" class="danger-actions"><el-button @click="transfer">转让空间</el-button><el-button type="danger" plain @click="dissolve">解散空间</el-button></div></el-tab-pane>
<el-tab-pane v-if="admin" label="权限审计" name="audit"><el-table :data="audit"><el-table-column prop="createdAt" label="时间" min-width="160"/><el-table-column prop="actorId" label="操作者" width="90"/><el-table-column prop="action" label="操作" min-width="170"/><el-table-column prop="target" label="对象" min-width="130"/></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="transferOpen" title="转让空间" width="480px" class="org-dialog"><form class="office-form" @submit.prevent="confirmTransfer"><label>接收管理员<el-select v-model="transferId" placeholder="选择团队内的系统管理员"><el-option v-for="m in transferCandidates" :key="m.userId" :label="m.name+'（'+m.username+'）'" :value="String(m.userId)"/></el-select></label><el-button type="primary" native-type="submit" :disabled="!transferId">确认转让</el-button></form></el-dialog>
<el-dialog v-model="deptOpen" title="部门" width="480px" class="org-dialog"><form class="office-form" @submit.prevent="saveDepartment"><label>名称<el-input v-model="deptForm.name" maxlength="50"/></label><label>上级<select v-model="deptForm.parentId"><option value="">根部门</option><option v-for="d in departments.filter(d=>d.id!==deptForm.id)" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><label>负责人<select v-model="deptForm.leaderId"><option value="">无</option><option v-for="m in members" :key="m.userId" :value="String(m.userId)">{{m.name}}</option></select></label><el-button native-type="submit" type="primary">保存部门</el-button></form></el-dialog>
<el-dialog v-model="roleOpen" title="角色" width="480px" class="org-dialog"><form class="office-form" @submit.prevent="saveRole"><label>名称<el-input v-model="roleForm.name" maxlength="50"/></label><el-checkbox v-for="p in operations" :key="p.key" v-model="roleForm.permissions[p.key]">{{p.label}}</el-checkbox><el-button native-type="submit" type="primary">保存角色</el-button></form></el-dialog>
<el-dialog v-model="memberOpen" title="成员权限" width="480px" class="org-dialog"><form class="office-form" @submit.prevent="saveMember"><label>部门<select v-model="memberForm.deptId"><option value="">未分配</option><option v-for="d in departments" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><label>自定义角色<select v-model="memberForm.customRoleId"><option value="">预设角色</option><option v-for="r in roles" :key="r.id" :value="String(r.id)">{{r.name}}</option></select></label><label>访问有效期<el-date-picker v-model="memberForm.expiresAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" clearable/></label><el-button native-type="submit" type="primary">保存成员权限</el-button></form></el-dialog></section></template>
<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {useWorkspaceStore} from '@/stores/workspace'
const props=defineProps<{admin:boolean;ownerId:string;userId:string}>(),workspace=useWorkspaceStore(),base=()=>`/space/${workspace.spaceId}/organization`,tab=ref('departments'),loading=ref(false),departments=ref<any[]>([]),roles=ref<any[]>([]),members=ref<any[]>([]),audit=ref<any[]>([]),space=ref<any>({}),quotaGB=ref(10),importInput=ref<HTMLInputElement>()
const operations=[{key:'view',label:'查看'},{key:'edit',label:'编辑'},{key:'download',label:'下载'},{key:'share',label:'分享'},{key:'delete',label:'删除'}]
function parsed(value:any){return typeof value==='string'?JSON.parse(value):value||{}}
const tree=computed(()=>{const build=(parent:any,seen:any[]=[],depth=0):any[]=>depth>50?[]:departments.value.filter(d=>String(d.parentId||'')===String(parent||'')&&!seen.includes(d.id)).map(d=>({...d,children:build(d.id,[...seen,d.id],depth+1)}));return build('')})
function allowed(p:any){const v=parsed(p);return operations.filter(o=>v[o.key]).map(o=>o.label).join('、')||'无权限'}
async function load(){loading.value=true;try{const r:any=await request.get(base());departments.value=r.data.departments;roles.value=r.data.roles;members.value=r.data.members;audit.value=r.data.audit||[];space.value=r.data.space;quotaGB.value=Number(space.value.quota)/1073741824}catch{}finally{loading.value=false}}
onMounted(load)
const deptOpen=ref(false),deptForm=ref<any>({}),roleOpen=ref(false),roleForm=ref<any>({permissions:{}}),memberOpen=ref(false),memberForm=ref<any>({})
function department(d:any={}){deptForm.value={...d,parentId:d.parentId?String(d.parentId):'',leaderId:d.leaderId?String(d.leaderId):''};deptOpen.value=true}
async function saveDepartment(){try{await request.post(base()+'/departments',deptForm.value);deptOpen.value=false;await load();ElMessage.success('部门已保存')}catch{}}
async function deleteDepartment(d:any){try{await ElMessageBox.confirm('删除部门“'+d.name+'”？','删除部门');await request.delete(base()+'/departments/'+d.id);await load()}catch{}}
function role(r:any={}){roleForm.value={...r,permissions:r.id?parsed(r.permissions):{view:true,edit:false,download:false,share:false,delete:false}};roleOpen.value=true}
async function saveRole(){try{await request.post(base()+'/roles',roleForm.value);roleOpen.value=false;await load();ElMessage.success('角色已保存')}catch{}}
async function deleteRole(r:any){try{await ElMessageBox.confirm('删除未使用的角色“'+r.name+'”？','删除角色');await request.delete(base()+'/roles/'+r.id);await load()}catch{}}
function member(m:any){memberForm.value={...m,deptId:m.deptId?String(m.deptId):'',customRoleId:m.customRoleId?String(m.customRoleId):''};memberOpen.value=true}
async function saveMember(){try{await request.put(base()+'/members/'+memberForm.value.userId,memberForm.value);memberOpen.value=false;await load();ElMessage.success('成员权限已保存')}catch{}}
async function saveSpace(){try{await request.put(base()+'/settings',{...space.value,quota:Math.round(quotaGB.value*1073741824)});await workspace.load();await load();ElMessage.success('空间设置已保存')}catch{}}
const transferOpen=ref(false),transferId=ref(''),transferCandidates=ref<any[]>([])
async function transfer(){try{const r:any=await request.get('/admin/roles/users');const admins=new Set(r.data.filter((u:any)=>u.platformRole==='SYSTEM_ADMIN').map((u:any)=>String(u.userId)));transferCandidates.value=members.value.filter(m=>String(m.userId)!==props.userId&&admins.has(String(m.userId)));if(!transferCandidates.value.length){ElMessage.warning('团队内没有其他系统管理员可接收');return}transferId.value='';transferOpen.value=true}catch{}}
async function confirmTransfer(){const target=transferCandidates.value.find(m=>String(m.userId)===transferId.value);if(!target)return;try{await ElMessageBox.confirm('转让给“'+target.name+'”后，你将失去此团队的管理权。','转让空间');await request.post(base()+'/transfer',{userId:target.userId});location.reload()}catch{}}
async function dissolve(){try{const {value}=await ElMessageBox.prompt('输入完整团队名称以解散','解散空间');await request.post(base()+'/dissolve',{confirm:value});workspace.select('');await workspace.load();location.reload()}catch{}}
async function importMembers(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];if(!f)return;const data=new FormData();data.append('file',f);try{const r:any=await request.post('/org/members/batch-import',data,{params:{spaceId:workspace.spaceId}});ElMessage.success(`新增 ${r.data.added} 名成员`);await load()}catch{}finally{input.value=''}}
</script>
<style scoped>.organization-panel{min-width:0}.dept-row{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%}.space-form{max-width:560px}.danger-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:32px}select{padding:8px;border:1px solid var(--c-border);border-radius:var(--radius-sm);background:var(--c-surface);color:var(--c-text);max-width:100%;min-width:0}:global(.org-dialog.el-dialog){max-width:calc(100vw - 24px);max-height:85dvh;overflow:auto}:global(.org-dialog .office-form label.el-checkbox){display:inline-flex}.material-symbols-outlined{font-size:18px}.organization-panel :deep(.el-tree-node__content){height:40px}</style>
